class Solution:
    def minInsertions(self, s: str) -> int:
        n = len(s)
        rev = s[::-1]
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            prev = [0] * (n + 1)
            for j in range(1, n + 1):
                if s[i - 1] == rev[j - 1]:
                    prev[j] = dp[j - 1] + 1
                else:
                    prev[j] = max(dp[j], prev[j - 1])
            dp = prev
        return n - dp[n]

